    def test_probe(self):
        self.runtime.stop_workers = lambda: self.fail("stop")
        self.states.update(ui="working", adapter="idle")
        self.now = 100.0
        self.completion("adapter")
        polls = []
        class Done(Exception): pass
        def poll():
            polls.append(self.now)
